describe("finding 3: durable worktree leases survive a parent crash", () => {
	it("refuses a second driver while a crashed parent's run lives, then reclaims", async (t) => {
		if (!linux) return t.skip("lease ownership uses /proc");
		const project = scratch("reg-crash-tree");
		initRepo(project);
		const tree = join(project, "..", "crash-tree");
		useHerdr({
			log: join(project, "..", "ct.json"),
			createWorktree(_name, cwd, branch, base) {
				execFileSync(
					"git",
					["worktree", "add", "-q", "-b", branch, tree, base],
					{
						cwd,
					},
				);
				return {
					path: tree,
					branch,
					workspaceId: "ws-crash",
					paneId: "root-crash",
				};
			},
		});
		await start(project, {
			name: "crash-worker",
			task: "Task",
			agent: "native-claude",
			worktree: { branch: "native/crash" },
		});
		const first = await resultFor("crash-worker");
		assert.equal(first.details.exitCode, 0, first.content);
		const manifestFile = first.details.worktree.manifestFile;
		const leasePath = nativeWorktreeLeaseFile(manifestFile);
		assert.equal(existsSync(leasePath), false, "released after confirmed exit");
		// A crashed parent left another native driver running in this worktree;
		// no in-memory holder exists in this (new) parent process.
		const crashed = liveOwnedRun(scratch("crashed-driver"), "crashed-driver");
		writeFileSync(leasePath, crashed.lease);
		try {
			const refused = await resume(project, {
				sessionPath: first.details.sessionFile,
				name: "crash-worker-2",
				message: "Continue",
			});
			assert.match(
				refused.content[0].text,
				/still leased by a native run: run crashed-driver may still be driving it[\s\S]*Nothing was launched/,
			);
			const blockers = __worktreeCleanupTest__.nativeLeaseBlockers(
				inventoryEntry(manifestFile),
			);
			assert.match(blockers[0] ?? "", /Native run lease holds the worktree/);
		} finally {
			killGroup(crashed.child.pid);
		}
		await waitFor(
			() =>
				__worktreeCleanupTest__.nativeLeaseBlockers(
					inventoryEntry(manifestFile),
				).length === 0,
		);
		const resumed = await resume(project, {
			sessionPath: first.details.sessionFile,
			name: "crash-worker-2",
			message: "Continue",
		});
		assert.equal(resumed.details.status, "started", resumed.content[0].text);
		const second = await resultFor("crash-worker-2");
		assert.equal(second.details.exitCode, 0, second.content);
		assert.equal(
			existsSync(leasePath),
			false,
			"the resumed run released it too",
		);
		writeFileSync(leasePath, "not json");
		const invalid = await resume(project, {
			sessionPath: first.details.sessionFile,
			message: "Again",
		});
		assert.match(invalid.content[0].text, /unreadable lease/);
	});
});

describe("finding 4: resume never changes the recorded mode", () => {
	it("rejects an autoExit override that would widen or narrow the mode", async () => {
		const project = scratch("reg-mode");
		useHerdr({ log: join(project, "..", "mode.json") });
		await start(project, {
			name: "mode-auto",
			task: "Task",
			agent: "native-claude",
		});
		const auto = await resultFor("mode-auto");
		const widened = await resume(project, {
			sessionPath: auto.details.sessionFile,
			message: "Continue",
			autoExit: false,
		});
		assert.match(
			widened.content[0].text,
			/autoExit: false would change its recorded autonomous mode[\s\S]*Nothing was launched/,
		);
		const restated = await resume(project, {
			sessionPath: auto.details.sessionFile,
			name: "mode-auto-2",
			message: "Continue",
			autoExit: true,
		});
		assert.equal(restated.details.status, "started", restated.content[0].text);
		await resultFor("mode-auto-2");

		const herdr = useHerdr({ log: join(project, "..", "mode-i.json") });
		await start(project, {
			name: "mode-human",
			task: "Pair",
			agent: "native-interactive",
		});
		const child = running("mode-human")!;
		await waitFor(() => child.native!.driver.turns[0].outcome === "completed");
		herdr.send(child.surface, "/exit");
		const human = await resultFor("mode-human");
		const narrowed = await resume(project, {
			sessionPath: human.details.sessionFile,
			message: "Continue",
			autoExit: true,
		});
		assert.match(narrowed.content[0].text, /recorded interactive mode/);
		const marker = markerV2(auto.details.sessionFile);
		assert.throws(
			() =>
				prepareNativeRun({
					id: "mode-mismatch",
					artifactDir: scratch("mode-artifacts"),
					cwd: project,
					name: "x",
					resume: {
						marker,
						markerFile: auto.details.sessionFile,
						message: "m",
						mode: "interactive",
					},
				}),
			/must keep the recorded autonomous mode/,
		);
	});
});

describe("finding 5: fallback needs positive evidence of no work", () => {
	const state = (patch: Partial<NativeHookState>): NativeHookState => ({
		sessionId: "44444444-4444-4444-8444-444444444444",
		phase: "ready",
		token: null,
		summary: null,
		error: null,
		untrackedSummary: null,
		untrackedTurns: 0,
		...patch,
	});
	const outcome = (hook: NativeHookState | null) => {
		const driver = createNativeDriver({
			mode: "autonomous",
			firstTurn: { id: "run", kind: "initial", ackTimeoutMs: 1_000 },
		});
		return nativeDriverOutcome(
			driver,
			{
				harness: "claude",
				label: "Claude Code",
				exitCommand: "/exit",
				exitTimeoutMs: 1_000,
				followUpAckTimeoutMs: 1_000,
				readState: () => hook,
			},
			{ reason: "done", exitCode: 1 },
		);
	};

	it("counts only a session receipt without any prompt receipt as never started", () => {
		assert.equal(outcome(state({})).neverStarted, true);
		assert.equal(
			outcome(null).neverStarted,
			false,
			"no receipt proves nothing",
		);
		assert.equal(
			outcome(state({ phase: "failed", token: "t", error: "rate_limit" }))
				.neverStarted,
			false,
			"a StopFailure follows an active turn",
		);
		assert.equal(
			outcome(state({ phase: "active", token: null })).neverStarted,
			false,
		);
		assert.equal(
			outcome(state({ phase: "untracked", untrackedTurns: 1 })).neverStarted,
			false,
		);
	});
});

describe("finding 6: owned descendants keep a run unresolved", () => {
	it("does not confirm exit while a token-carrying descendant outlives the wrapper", async (t) => {
		if (!linux) return t.skip("descendant scans use /proc");
		const dir = scratch("reg-descendant");
		const run = createProcessRun("desc-run", join(dir, "process.json"));
		const script = stageScript(
			supervisedCommand(
				`sleep 30 >/dev/null 2>&1 & echo $! > ${join(dir, "child.pid")}`,
				run,
			),
			{ scriptPath: join(dir, "desc.sh") },
		);
		execFileSync("bash", [script]);
		assert.equal(readProcessReceipt(run)?.exitCode, 0, "the wrapper exited");
		const pid = Number(readFileSync(join(dir, "child.pid"), "utf8"));
		try {
			const exit = confirmProcessExit(run);
			assert.equal(exit.kind, "unconfirmed");
			assert.match(
				exit.kind === "unconfirmed" ? exit.reason : "",
				/owned descendant/,
			);
		} finally {
			process.kill(pid, "SIGKILL");
		}
		await waitFor(() => confirmProcessExit(run).kind === "confirmed");
	});

	it("retains leases and blocks resume until a lingering descendant exits", async (t) => {
		if (!linux) return t.skip("descendant scans use /proc");
		const project = scratch("reg-linger");
		const log = join(project, "..", "linger.json");
		useHerdr({ log, env: { FAKE_LINGER: "1" } });
		await start(project, {
			name: "linger",
			task: "Task",
			agent: "native-claude",
		});
		const result = await resultFor("linger");
		assert.notEqual(result.details.exitCode, 0, "never a clean completion");
		assert.equal(result.details.native.processExit, "unconfirmed");
		assert.match(result.details.errorMessage, /owned descendant process/);
		assert.equal(result.details.native.resume.available, false);
		const markerFile = result.details.sessionFile;
		assert.equal(existsSync(`${markerFile}.lease`), true, "session lease held");
		const blocked = await resume(project, {
			sessionPath: markerFile,
			message: "Continue",
		});
		assert.match(
			blocked.content[0].text,
			/still leased|exit is still unconfirmed/,
		);
		const lingering = fixtureEvents(log).find(
			(event) => event.lingering,
		)?.lingering;
		process.kill(lingering, "SIGKILL");
		await waitFor(() =>
			testApi
				.reconcileUnresolvedNativeRuns()
				.every((entry) => entry.run.markerFile !== markerFile),
		);
		assert.equal(
			existsSync(`${markerFile}.lease`),
			false,
			"released after exit",
		);
	});
});

describe("late exit confirmation closes accepted ordinary panes", () => {
	const lingeringPid = (log: string): number =>
		fixtureEvents(log).find((event) => event.lingering)?.lingering;
	const settle = () => new Promise((resolve) => setTimeout(resolve, 150));
	/**
	 * When the parent is first handed this child's result, end the lingering
	 * descendant and let a reconciliation release the run, all before the
	 * send returns: reconciliation wins between settlement and acceptance.
	 */
	const reconcileOnResult = (name: string, log: string, child: any) => {
		const raced = { won: false };
		beforeSend.hook = (message) => {
			if (message.customType !== "subagent_result") return;
			if (message.details?.name !== name) return;
			beforeSend.hook = undefined;
			process.kill(lingeringPid(log), "SIGKILL");
			const sleeper = new Int32Array(new SharedArrayBuffer(4));
			const deadline = Date.now() + 5_000;
			while (
				confirmProcessExit(child.native.processRun).kind !== "confirmed" &&
				Date.now() < deadline
			)
				Atomics.wait(sleeper, 0, 0, 20);
			testApi.reconcileUnresolvedNativeRuns();
			raced.won = !testApi.unresolvedNativeRuns().has(child.id);
		};
		return raced;
	};

	it("closes the pane exactly once after accepted delivery and late exit", async (t) => {
		if (!linux) return t.skip("descendant scans use /proc");
		const project = scratch("late-close");
		const log = join(project, "..", "late-close.json");
		const herdr = useHerdr(
			{ log, env: { FAKE_LINGER: "1" } },
			{ lateExitRecheckMs: 20 },
		);
		await start(project, {
			name: "late-close",
			task: "Task",
			agent: "native-claude",
		});
		const child = running("late-close");
		assert.ok(child);
		const result = await resultFor("late-close");
		const surface = result.details.native.surface;
		assert.equal(result.details.native.processExit, "unconfirmed");
		assert.equal(surface, child.surface);
		await settle();
		assert.deepEqual(herdr.closed, [], "re-checks keep a live run's pane");
		assert.equal(existsSync(`${result.details.sessionFile}.lease`), true);
		process.kill(lingeringPid(log), "SIGKILL");
		// No inventory call: the scheduled re-check alone closes the pane.
		await waitFor(() => herdr.closed.includes(surface));
		assert.equal(existsSync(`${result.details.sessionFile}.lease`), false);
		testApi.closePaneAfterLateExit(child, result.details.native);
		testApi.reconcileUnresolvedNativeRuns();
		await settle();
		assert.deepEqual(herdr.closed, [surface], "closed once, nothing else");
	});

	it("closes once when reconciliation wins before accepted delivery", async (t) => {
		if (!linux) return t.skip("descendant scans use /proc");
		const project = scratch("late-race");
		const log = join(project, "..", "late-race.json");
		const herdr = useHerdr({ log, env: { FAKE_LINGER: "1" } });
		await start(project, {
			name: "late-race",
			task: "Task",
			agent: "native-claude",
		});
		const child = running("late-race");
		assert.ok(child);
		const raced = reconcileOnResult("late-race", log, child);
		try {
			const result = await resultFor("late-race");
			assert.equal(raced.won, true, "released before the send returned");
			assert.equal(result.details.native.processExit, "unconfirmed");
			assert.equal(existsSync(`${result.details.sessionFile}.lease`), false);
			await waitFor(() => herdr.closed.includes(child.surface));
			testApi.closePaneAfterLateExit(child, result.details.native);
			testApi.reconcileUnresolvedNativeRuns();
			await settle();
			assert.deepEqual(herdr.closed, [child.surface], "closed once");
		} finally {
			beforeSend.hook = undefined;
		}
	});

	it("closes a resumed pane once when reconciliation wins first", async (t) => {
		if (!linux) return t.skip("descendant scans use /proc");
		const project = scratch("late-race-resume");
		useHerdr({ log: join(project, "..", "first.json") });
		await start(project, {
			name: "late-resume",
			task: "Task",
			agent: "native-claude",
		});
		const first = await resultFor("late-resume");
		assert.equal(first.details.native.processExit, "confirmed");
		const log = join(project, "..", "late-race-resume.json");
		const herdr = useHerdr({ log, env: { FAKE_LINGER: "1" } });
		const resumed = await resume(project, {
			sessionPath: first.details.sessionFile,
			name: "late-resume-2",
			message: "Continue",
		});
		assert.equal(resumed.details.status, "started", resumed.content[0].text);
		const child = running("late-resume-2");
		assert.ok(child);
		const raced = reconcileOnResult("late-resume-2", log, child);
		try {
			const result = await resultFor("late-resume-2");
			assert.equal(raced.won, true);
			assert.equal(result.details.native.processExit, "unconfirmed");
			await waitFor(() => herdr.closed.includes(child.surface));
			await settle();
			assert.deepEqual(herdr.closed, [child.surface], "closed once");
		} finally {
			beforeSend.hook = undefined;
		}
	});

	it("keeps the pane when the raced delivery is rejected", async (t) => {
		if (!linux) return t.skip("descendant scans use /proc");
		const project = scratch("late-race-rejected");
		const log = join(project, "..", "late-race-rejected.json");
		const herdr = useHerdr(
			{ log, env: { FAKE_LINGER: "1" } },
			{ lateExitRecheckMs: 20 },
		);
		await start(project, {
			name: "late-rejected",
			task: "Task",
			agent: "native-claude",
		});
		const child = running("late-rejected");
		assert.ok(child);
		const raced = reconcileOnResult("late-rejected", log, child);
		sendFailures.match = (message) => message.details?.name === "late-rejected";
		sendFailures.remaining = 1;
		try {
			await waitFor(() => sendFailures.remaining === 0, 15_000);
			await waitFor(() => !running("late-rejected"));
			assert.equal(raced.won, true);
			await settle();
			assert.equal(
				sent.some((message) => message.details?.name === "late-rejected"),
				false,
				"the send was rejected and nothing else was delivered",
			);
			testApi.closePaneAfterLateExit(child, {
				harness: "claude",
				markerFile: child.sessionFile,
				processExit: "unconfirmed",
			});
			await settle();
			assert.deepEqual(herdr.closed, [], "a rejected result keeps its pane");
		} finally {
			beforeSend.hook = undefined;
			sendFailures.remaining = 0;
		}
	});

	it("closes an ordinary pane once after an accepted watcher error", async (t) => {
		if (!linux) return t.skip("exit confirmation uses /proc");
		const project = scratch("late-thrown");
		const herdr = useHerdr(
			{
				log: join(project, "..", "late-thrown.json"),
				env: { FAKE_EXIT_AFTER_STOP: "1" },
				waitForExit: true,
			},
			{
				watch: {
					// The settlement and the watcher's exit re-check both fail.
					onTurnSettled(turn) {
						if (turn.outcome === "completed")
							throw new Error("injected settlement failure");
					},
					confirmExit() {
						throw new Error("injected exit check failure");
					},
				},
			},
		);
		await start(project, {
			name: "late-thrown",
			task: "Task",
			agent: "native-claude",
		});
		const child = running("late-thrown");
		assert.ok(child);
		const result = await resultFor("late-thrown");
		assert.match(result.content, /injected exit check failure/);
		assert.equal(result.details.native.processExit, "confirmed");
		await waitFor(() => herdr.closed.includes(child.surface));
		await settle();
		assert.deepEqual(herdr.closed, [child.surface], "closed once");
	});

	for (const failing of [false, true])
		for (const rejected of [false, true])
			it(`${rejected ? "keeps" : "closes"} a resumed pane when its ${failing ? "watcher error" : "result"} send is ${rejected ? "rejected" : "accepted"}`, async (t) => {
				if (!linux) return t.skip("exit confirmation uses /proc");
				const id = `resume-send-${failing ? "error" : "result"}-${rejected ? "rejected" : "accepted"}`;
				const project = scratch(id);
				useHerdr({ log: join(project, "..", `${id}-1.json`) });
				await start(project, {
					name: id,
					task: "Task",
					agent: "native-claude",
				});
				const first = await resultFor(id);
				assert.equal(first.details.native.processExit, "confirmed");
				const herdr = useHerdr(
					{
						log: join(project, "..", `${id}-2.json`),
						env: { FAKE_EXIT_AFTER_STOP: "1" },
						waitForExit: true,
					},
					failing
						? {
								watch: {
									onTurnSettled(turn) {
										if (turn.outcome === "completed")
											throw new Error("injected settlement failure");
									},
									confirmExit() {
										throw new Error("injected exit check failure");
									},
								},
							}
						: {},
				);
				const name = `${id}-2`;
				let attempts = 0;
				const unhandled: unknown[] = [];
				const onUnhandled: NodeJS.UnhandledRejectionListener = (reason) =>
					unhandled.push(reason);
				process.on("unhandledRejection", onUnhandled);
				beforeSend.hook = (message) => {
					if (message.details?.name === name) attempts++;
				};
				sendFailures.match = (message) => message.details?.name === name;
				sendFailures.remaining = rejected ? 1 : 0;
				try {
					const resumed = await resume(project, {
						sessionPath: first.details.sessionFile,
						name,
						message: "Continue",
					});
					assert.equal(
						resumed.details.status,
						"started",
						resumed.content[0].text,
					);
					const child = running(name);
					assert.ok(child);
					await waitFor(() => attempts > 0 && !running(name), 15_000);
					await settle();
					assert.equal(attempts, 1, "sent exactly once, never re-sent");
					assert.deepEqual(unhandled, []);
					const delivered = sent.filter(
						(message) => message.details?.name === name,
					);
					if (rejected) {
						assert.deepEqual(delivered, []);
						assert.deepEqual(
							herdr.closed,
							[],
							"a rejected result keeps its pane",
						);
					} else {
						assert.equal(delivered.length, 1);
						assert.equal(delivered[0].details.native.processExit, "confirmed");
						if (failing)
							assert.match(delivered[0].content, /Native resume error/);
						assert.deepEqual(herdr.closed, [child.surface], "closed once");
					}
				} finally {
					process.off("unhandledRejection", onUnhandled);
					beforeSend.hook = undefined;
					sendFailures.remaining = 0;
					sendFailures.match = undefined;
				}
			});

	it("keeps the pane when the parent never accepted the result", async (t) => {
		if (!linux) return t.skip("descendant scans use /proc");
		const project = scratch("late-suppressed");
		const log = join(project, "..", "late-suppressed.json");
		const herdr = useHerdr(
			{ log, env: { FAKE_LINGER: "1" } },
			{ lateExitRecheckMs: 20 },
		);
		await start(project, {
			name: "late-suppressed",
			task: "Task",
			agent: "native-claude",
		});
		const child = running("late-suppressed");
		assert.ok(child);
		// As a non-preserving parent shutdown does before completion.
		child.lifecycle = { ...child.lifecycle, delivery: "suppressed" };
		await waitFor(() => !running("late-suppressed"), 15_000);
		const entry = testApi.unresolvedNativeRuns().get(child.id);
		assert.ok(entry, "retained as unresolved");
		assert.equal(entry.closePaneOnExit, undefined);
		process.kill(lingeringPid(log), "SIGKILL");
		await waitFor(() =>
			testApi.reconcileUnresolvedNativeRuns().every((other) => other !== entry),
		);
		await settle();
		assert.equal(existsSync(`${entry.run.markerFile}.lease`), false);
		assert.equal(
			sent.some((message) => message.details?.name === "late-suppressed"),
			false,
		);
		assert.deepEqual(herdr.closed, [], "an unaccepted result keeps its pane");
	});

	it("never marks worktree, persistent, interactive, nested, or other runs", () => {
		const herdr = useHerdr({ log: join(scratch("late-ineligible"), "x.json") });
		const result = (processExit: string): any => ({ processExit });
		const unconfirmed = result("unconfirmed");
		const fake = (
			id: string,
			extra: {
				worktree?: { path: string };
				persistent?: boolean;
				nestedOf?: { requesterId: string };
			},
			mode = "autonomous",
		): any => ({
			id,
			surface: `pane-${id}`,
			native: { driver: { mode } },
			...extra,
		});
		const cases = [
			fake("tree", { worktree: { path: "/tmp/tree" } }),
			fake("persistent", { persistent: true }),
			fake("interactive", {}, "interactive"),
			fake("nested", { nestedOf: { requesterId: "parent" } }),
		];
		const runs = testApi.unresolvedNativeRuns();
		try {
			for (const child of cases) {
				runs.set(child.id, { run: child.native });
				testApi.closePaneAfterLateExit(child, unconfirmed);
				assert.equal(runs.get(child.id)?.closePaneOnExit, undefined, child.id);
			}
			// Another run under the same ID, a confirmed exit, and an
			// already released run never take this pane.
			const other = fake("other", {});
			runs.set(other.id, { run: fake("other-run", {}).native });
			testApi.closePaneAfterLateExit(other, unconfirmed);
			assert.equal(runs.get(other.id)?.closePaneOnExit, undefined);
			const confirmed = fake("confirmed", {});
			runs.set(confirmed.id, { run: confirmed.native });
			testApi.closePaneAfterLateExit(confirmed, result("confirmed"));
			assert.equal(runs.get(confirmed.id)?.closePaneOnExit, undefined);
			testApi.closePaneAfterLateExit(fake("released", {}), unconfirmed);
			assert.equal(runs.has("released"), false);
			assert.deepEqual(herdr.closed, []);
		} finally {
			for (const id of [
				...cases.map((child) => child.id),
				"other",
				"confirmed",
			])
				runs.delete(id);
		}
	});

	it("closes a released run's pane only after its exit is confirmed again", () => {
		let confirm: () => any = () => ({ kind: "confirmed", unreadableCount: 0 });
		const herdr = useHerdr(
			{ log: join(scratch("late-released"), "x.json") },
			{ watch: { confirmExit: () => confirm() } },
		);
		const accepted = (surface?: string): any => ({
			processExit: "unconfirmed",
			surface,
		});
		const late = testApi.lateReleasedNativeRuns();
		const released = (id: string, mode = "autonomous"): any => {
			const native: any = { driver: { mode }, processRun: { id } };
			late.add(native);
			return { id, surface: `pane-${id}`, native };
		};
		const unconfirmed = released("unconfirmed");
		confirm = () => ({ kind: "unconfirmed", reason: "still running" });
		testApi.closePaneAfterLateExit(unconfirmed, accepted());
		const throwing = released("throwing");
		confirm = () => {
			throw new Error("scan failed");
		};
		testApi.closePaneAfterLateExit(throwing, accepted());
		confirm = () => ({ kind: "confirmed", unreadableCount: 0 });
		const elsewhere = released("elsewhere");
		testApi.closePaneAfterLateExit(elsewhere, accepted("pane-other"));
		testApi.closePaneAfterLateExit(
			released("interactive", "interactive"),
			accepted(),
		);
		assert.deepEqual(
			herdr.closed,
			[],
			"unproven or ineligible runs keep panes",
		);
		const confirmed = released("confirmed");
		testApi.closePaneAfterLateExit(confirmed, accepted(confirmed.surface));
		testApi.closePaneAfterLateExit(confirmed, accepted(confirmed.surface));
		testApi.closePaneAfterLateExit(unconfirmed, accepted());
		assert.deepEqual(herdr.closed, ["pane-confirmed"], "closed exactly once");
	});
});

describe("finding 7: persistent delivery is recoverable and deduplicated", () => {
	it("retries a failed parent send without duplicating or stranding the task", async () => {
		const project = scratch("reg-flaky");
		useHerdr({ log: join(project, "..", "flaky.json") });
		sendFailures.match = (message) =>
			/"flaky-spec" completed task/.test(message.content ?? "");
		sendFailures.remaining = 2;
		await start(project, {
			name: "flaky-spec",
			task: "First",
			agent: "native-persistent",
		});
		await waitForMessage((message) =>
			/"flaky-spec" completed task/.test(message.content ?? ""),
		);
		assert.equal(sendFailures.remaining, 0, "both transient failures happened");
		const child = running("flaky-spec")!;
		await waitFor(() => testApi.persistentSpecialistState(child) === "idle");
		const delivered = () =>
			readPersistentDeliveryLedger(child.sessionFile).filter(
				(entry) => entry.outcome === "delivered",
			).length;
		await new Promise((resolve) => setTimeout(resolve, 150));
		assert.equal(
			sent.filter((message) =>
				/"flaky-spec" completed task/.test(message.content ?? ""),
			).length,
			1,
		);
		assert.equal(delivered(), 1);

		// A stale parent API (as before /reload) keeps the next task owed and
		// the specialist busy; the reloaded API then delivers it exactly once.
		const stale = createApi();
		stale.sendMessage = () => {
			throw new Error("stale parent session");
		};
		subagentsModule.default(stale);
		assert.equal(
			testApi.handleSubagentSend({ name: "flaky-spec", message: "Second" })
				.details.outcome,
			"dispatched",
		);
		await waitFor(() => child.native!.driver.turns[1]?.outcome === "completed");
		await new Promise((resolve) => setTimeout(resolve, 150));
		assert.equal(testApi.persistentSpecialistState(child), "working");
		assert.equal(
			testApi.handleSubagentSend({ name: "flaky-spec", message: "Third" })
				.details.outcome,
			"rejected-busy",
		);
		subagentsModule.default(api);
		await waitFor(() => testApi.persistentSpecialistState(child) === "idle");
		assert.equal(
			sent.filter((message) =>
				/"flaky-spec" completed task/.test(message.content ?? ""),
			).length,
			2,
		);
		assert.equal(delivered(), 2);
		testApi.handleSubagentStop({ name: "flaky-spec" }, api);
		await waitForMessage(
			(message) =>
				message.customType === "subagent_stop" &&
				message.details?.facts?.sessionFile === child.sessionFile,
		);
	});
});

describe("finding 8: skill assets are snapshotted and bound to resume", () => {
	it("delivers and resumes only the private snapshot, and rejects tampering", async () => {
		const project = scratch("reg-skill");
		const skillDir = join(scratch("reg-skill-source"), "probe-skill");
		mkdirSync(skillDir, { recursive: true });
		writeFileSync(
			join(skillDir, "SKILL.md"),
			"---\nname: probe-skill\n---\nRead ref.md first.\n",
		);
		writeFileSync(join(skillDir, "ref.md"), "original reference");
		skillCommands.push({
			name: "skill:probe-skill",
			source: "skill",
			sourceInfo: { path: join(skillDir, "SKILL.md") },
		});
		writeRole("native-skilled", [
			"cli: claude",
			"auto-exit: true",
			"tools: read, bash",
			"skills: probe-skill",
		]);
		const log = join(project, "..", "skill.json");
		useHerdr({ log });
		await start(project, {
			name: "skilled",
			task: "Task",
			agent: "native-skilled",
		});
		const first = await resultFor("skilled");
		assert.equal(first.details.exitCode, 0, first.content);
		const marker = markerV2(first.details.sessionFile);
		const snapshot = marker.loadout.skills[0].snapshot!;
		assert.ok(
			snapshot.dir.includes(join("artifacts", "parent", "native-skills")),
		);
		const prompt: string = JSON.parse(readFileSync(log, "utf8")).args.at(-1);
		assert.ok(prompt.includes(`location="${join(snapshot.dir, "SKILL.md")}"`));
		assert.ok(
			!prompt.includes(skillDir),
			"the live installation is never referenced",
		);
		assert.equal(
			readFileSync(join(snapshot.dir, "ref.md"), "utf8"),
			"original reference",
		);
		// Editing the live skill does not affect the recorded loadout.
		writeFileSync(join(skillDir, "ref.md"), "edited live");
		const resumed = await resume(project, {
			sessionPath: first.details.sessionFile,
			name: "skilled-2",
			message: "Continue",
		});
		assert.equal(resumed.details.status, "started", resumed.content[0].text);
		await resultFor("skilled-2");
		// Tampering with the snapshot fails resume closed.
		chmodSync(join(snapshot.dir, "ref.md"), 0o600);
		writeFileSync(join(snapshot.dir, "ref.md"), "tampered");
		const refused = await resume(project, {
			sessionPath: first.details.sessionFile,
			message: "Again",
		});
		assert.match(
			refused.content[0].text,
			/skill "probe-skill" snapshot [^\n]* no longer matches[\s\S]*Nothing was launched/,
		);
	});
});

describe("finding 6 (adjacent): descendant checks never fail open on Linux", () => {
	it("keeps a wrapper exit unconfirmed when /proc enumeration fails", () => {
		const dir = scratch("reg-enumeration");
		const run = createProcessRun("enum-run", join(dir, "process.json"));
		writeFileSync(
			run.receiptFile,
			JSON.stringify({
				version: 1,
				runId: "enum-run",
				owner: run.ownerToken,
				pid: 424242,
				exitCode: 0,
			}),
		);
		const broken = {
			procRoot: join(dir, "missing-proc"),
			uid: null,
			isAlive: () => false,
			kill: () => assert.fail("never signals"),
		};
		const exit = confirmProcessExit(run, broken);
		assert.equal(exit.kind, "unconfirmed");
		const noProc = { ...broken, procRoot: null };
		assert.equal(
			confirmProcessExit(run, noProc).kind,
			"unconfirmed",
			"a wrapper receipt alone never confirms exit without a descendant scan",
		);
	});
});

