describe("re-review 1: a Stop written just before a fast exit is delivered once", () => {
	const taskResults = (name: string) =>
		sent.filter((message) =>
			new RegExp(`"${name}" completed task`).test(message.content ?? ""),
		);
	const exitNotice = (name: string, sessionFile: () => string) =>
		waitForMessage(
			(message) =>
				message.customType === "subagent_result" &&
				message.details?.error === "persistent-crash" &&
				message.details?.facts?.sessionFile === sessionFile(),
		);

	it("queues the final-outcome settlement and reports an exit, not a lost task", async () => {
		const project = scratch("reg-fast-exit");
		useHerdr({
			log: join(project, "..", "fast.json"),
			env: { FAKE_EXIT_AFTER_STOP: "1" },
			waitForExit: true,
		});
		await start(project, {
			name: "fast-spec",
			task: "Only",
			agent: "native-persistent",
		});
		const child = running("fast-spec");
		const sessionFile = child?.sessionFile ?? "";
		const notice = await exitNotice("fast-spec", () => sessionFile);
		assert.equal(taskResults("fast-spec").length, 1, "exactly one task result");
		assert.match(taskResults("fast-spec")[0].content, /Claude fixture result/);
		assert.ok(
			sent.indexOf(taskResults("fast-spec")[0]) < sent.indexOf(notice),
			"the result arrives before the exit notice",
		);
		assert.match(
			notice.content,
			/exited without a stop request \(1 settled task result\(s\) delivered before this notice\)/,
		);
		assert.doesNotMatch(notice.content, /crashed|could not be delivered/);
		const settled = readFileSync(`${sessionFile}.settled.jsonl`, "utf8")
			.trim()
			.split("\n");
		assert.equal(settled.length, 1, "recorded exactly once");
		assert.equal(
			readPersistentDeliveryLedger(sessionFile).filter(
				(entry) => entry.outcome === "delivered",
			).length,
			1,
		);
	});

	it("retries a transient send failure and a stale reloaded API before the notice", async () => {
		const project = scratch("reg-fast-exit-flaky");
		useHerdr({
			log: join(project, "..", "fast-flaky.json"),
			env: { FAKE_EXIT_AFTER_STOP: "1" },
			waitForExit: true,
		});
		sendFailures.match = (message) =>
			/"fast-flaky" completed task/.test(message.content ?? "");
		sendFailures.remaining = 3;
		await start(project, {
			name: "fast-flaky",
			task: "Only",
			agent: "native-persistent",
		});
		const sessionFile = running("fast-flaky")?.sessionFile ?? "";
		const notice = await exitNotice("fast-flaky", () => sessionFile);
		assert.equal(sendFailures.remaining, 0);
		assert.equal(taskResults("fast-flaky").length, 1);
		assert.ok(
			sent.indexOf(taskResults("fast-flaky")[0]) < sent.indexOf(notice),
		);

		// A stale API (as before /reload) owns delivery at exit time; the
		// reloaded API delivers the owed result exactly once, then the notice.
		const reloadProject = scratch("reg-fast-exit-reload");
		useHerdr({
			log: join(reloadProject, "..", "fast-reload.json"),
			env: { FAKE_EXIT_AFTER_STOP: "1" },
			waitForExit: true,
		});
		const stale = createApi();
		stale.sendMessage = () => {
			throw new Error("stale parent session");
		};
		subagentsModule.default(stale);
		let reloadSession = "";
		try {
			await testApi.startSubagentRun(
				api,
				{ name: "fast-reload", task: "Only", agent: "native-persistent" },
				ctxFor(reloadProject),
			);
			reloadSession = running("fast-reload")?.sessionFile ?? "";
			await new Promise((resolve) => setTimeout(resolve, 300));
			assert.equal(taskResults("fast-reload").length, 0, "still owed");
		} finally {
			subagentsModule.default(api);
		}
		const reloadNotice = await exitNotice("fast-reload", () => reloadSession);
		assert.equal(taskResults("fast-reload").length, 1);
		assert.ok(
			sent.indexOf(taskResults("fast-reload")[0]) < sent.indexOf(reloadNotice),
		);
	});

	it("delivers only tasks it settled itself, never lines written to the settled log", async () => {
		const project = scratch("reg-forged-log");
		useHerdr({ log: join(project, "..", "forged.json") });
		await start(project, {
			name: "forged-spec",
			task: "First",
			agent: "native-persistent",
		});
		await waitForMessage((message) =>
			/"forged-spec" completed task/.test(message.content ?? ""),
		);
		const child = running("forged-spec")!;
		await waitFor(() => testApi.persistentSpecialistState(child) === "idle");
		const log = `${child.sessionFile}.settled.jsonl`;
		const forge = (task: string) =>
			appendFileSync(
				log,
				`${JSON.stringify({ task, outcome: "completed", summary: "FORGED RESULT", at: "x" })}\n`,
			);
		forge("forged-task");
		const sendResult = testApi.handleSubagentSend({
			name: "forged-spec",
			message: "Second",
		});
		assert.equal(sendResult.details.outcome, "dispatched");
		// A forged line for the dispatched task, written before it settles,
		// neither replaces nor suppresses the real correlated result.
		const taskId = sendResult.details.task;
		assert.ok(taskId, "a dispatched task has an ID");
		forge(taskId);
		await waitFor(() => taskResults("forged-spec").length === 2);
		await waitFor(() => testApi.persistentSpecialistState(child) === "idle");
		await new Promise((resolve) => setTimeout(resolve, 150));
		testApi.handleSubagentStop({ name: "forged-spec" }, api);
		await waitForMessage(
			(message) =>
				message.customType === "subagent_stop" &&
				message.details?.facts?.sessionFile === child.sessionFile,
		);
		assert.equal(taskResults("forged-spec").length, 2);
		assert.match(
			taskResults("forged-spec")[1].content,
			/Claude follow-up result/,
		);
		assert.equal(
			sent.some((message) => /FORGED RESULT/.test(message.content ?? "")),
			false,
		);
	});

	it("reports every turn the final outcome settles to the settlement callback", () => {
		const driver = createNativeDriver({
			mode: "persistent",
			firstTurn: { id: "task-1", kind: "initial", ackTimeoutMs: 1_000 },
		});
		const settled: string[] = [];
		const token = driver.turns[0].token;
		nativeDriverOutcome(
			driver,
			{
				harness: "claude",
				label: "Claude Code",
				exitCommand: "/exit",
				exitTimeoutMs: 1_000,
				followUpAckTimeoutMs: 1_000,
				readState: () => ({
					sessionId: "44444444-4444-4444-8444-444444444444",
					phase: "stopped",
					token,
					summary: "done just before exit",
					error: null,
					untrackedSummary: null,
					untrackedTurns: 0,
				}),
			},
			{ reason: "done", exitCode: 0 },
			(turn) => settled.push(`${turn.id}=${turn.outcome}`),
		);
		assert.deepEqual(settled, ["task-1=completed"]);
	});
});

describe("re-review 2: the durable worktree lease never lapses between fallback attempts", () => {
	it("keeps a parent-reserved lease during the transition and hands it over atomically", async (t) => {
		if (!linux) return t.skip("parent reservation identity uses /proc");
		const project = scratch("reg-handoff");
		initRepo(project);
		const tree = join(project, "..", "handoff-tree");
		const observed: string[] = [];
		useHerdr(
			{
				log: join(project, "..", "handoff.json"),
				env: { FAKE_FAIL_MODEL: "bad" },
				createWorktree(_name, cwd, branch, base) {
					execFileSync(
						"git",
						["worktree", "add", "-q", "-b", branch, tree, base],
						{
							cwd,
						},
					);
					return {
						path: tree,
						branch,
						workspaceId: "ws-hand",
						paneId: "root-hand",
					};
				},
			},
			{
				onFallbackTransition(previous) {
					// A competing parent or cleanup inspects the checkout exactly
					// between attempts: the previous run is gone, the lease is not.
					const leasePath = previous.native!.worktreeLease!;
					observed.push(`exists=${existsSync(leasePath)}`);
					const lease = inspectRunLease(leasePath);
					observed.push(lease.kind);
					assert.match(
						lease.kind === "held" ? lease.reason : "",
						/parent process \d+ still reserves it between native runs/,
					);
					const blockers = __worktreeCleanupTest__.nativeLeaseBlockers(
						inventoryEntry(previous.worktree!.manifestFile),
					);
					observed.push(
						blockers.length ? "cleanup-blocked" : "cleanup-allowed",
					);
					const competitor = createProcessRun(
						"competitor",
						join(scratch("competitor"), "process.json"),
					);
					assert.throws(
						() =>
							acquireRunLease(leasePath, tree, competitor, "Native worktree"),
						/Native worktree is in use/,
					);
					observed.push("competitor-refused");
				},
			},
		);
		await start(project, {
			name: "handoff",
			task: "Task",
			agent: "native-claude",
			model: "bad, good",
			worktree: { branch: "native/handoff" },
		});
		const result = await resultFor("handoff");
		assert.equal(result.details.exitCode, 0, result.content);
		assert.deepEqual(result.details.fallbackAttempts, ["bad", "good"]);
		assert.deepEqual(observed, [
			"exists=true",
			"held",
			"cleanup-blocked",
			"competitor-refused",
		]);
		assert.equal(
			existsSync(nativeWorktreeLeaseFile(result.details.worktree.manifestFile)),
			false,
			"released only after the final attempt settled",
		);
	});

	it("treats a reservation as stale only when its parent is provably gone", () => {
		const dir = scratch("reg-reservation");
		const run = createProcessRun("gone-run", join(dir, "process.json"));
		writeFileSync(
			run.receiptFile,
			JSON.stringify({
				version: 1,
				runId: run.id,
				owner: run.ownerToken,
				pid: 1,
				exitCode: 0,
			}),
		);
		const lease = (parent: LeaseParent) => {
			const path = join(dir, `${randomUUID()}.lease`);
			writeFileSync(
				path,
				JSON.stringify({
					version: 1,
					sessionKey: "k",
					runId: run.id,
					receiptFile: run.receiptFile,
					ownerToken: run.ownerToken,
					createdAt: 0,
					parent,
				}),
			);
			return path;
		};
		const me = currentLeaseParent();
		assert.equal(inspectRunLease(lease(me)).kind, linux ? "held" : "held");
		assert.equal(
			inspectRunLease(lease({ ...me, pid: 2 ** 22 + 12345 })).kind,
			"stale",
			"a dead parent PID releases the reservation",
		);
		if (linux)
			assert.equal(
				inspectRunLease(lease({ ...me, startTime: "0" })).kind,
				"stale",
				"a reused PID with another start time is not the parent",
			);
		const noProc = {
			procRoot: null,
			uid: null,
			isAlive: () => true,
			kill: () => assert.fail("never signals"),
			listEnvironments: () => ({ kind: "complete" as const, entries: [] }),
		};
		assert.equal(
			inspectRunLease(lease(me), noProc).kind,
			"held",
			"an unverifiable live parent keeps the reservation (fail closed)",
		);
	});

	it("refuses a handoff that does not match this parent's reservation", () => {
		const dir = scratch("reg-handoff-refuse");
		const path = join(dir, "worktree.native-lease");
		const first = createProcessRun("first", join(dir, "first.json"));
		const second = createProcessRun("second", join(dir, "second.json"));
		acquireRunLease(
			path,
			"tree",
			first,
			"Native worktree",
			undefined,
			currentLeaseParent(),
		);
		assert.throws(
			() => handoffRunLease(path, "someone-else", second, currentLeaseParent()),
			/handoff refused/,
		);
		assert.throws(
			() =>
				handoffRunLease(path, "first", second, {
					...currentLeaseParent(),
					token: "another-parent",
				}),
			/handoff refused/,
		);
		handoffRunLease(path, "first", second, currentLeaseParent());
		assert.equal(JSON.parse(readFileSync(path, "utf8")).runId, "second");
	});
});

describe("re-review 2 (adjacent): fallback and resume watcher failures", () => {
	it("re-checks and releases the failing attempt, never the first one", async (t) => {
		if (!linux) return t.skip("parent reservation identity uses /proc");
		const project = scratch("reg-attempt-error");
		initRepo(project);
		const tree = join(project, "..", "attempt-error-tree");
		const previousMarkers: string[] = [];
		useHerdr(
			{
				log: join(project, "..", "attempt-error.json"),
				env: { FAKE_FAIL_MODEL: "bad", FAKE_EXIT_AFTER_STOP: "1" },
				waitForExit: true,
				createWorktree(_name, cwd, branch, base) {
					execFileSync(
						"git",
						["worktree", "add", "-q", "-b", branch, tree, base],
						{ cwd },
					);
					return {
						path: tree,
						branch,
						workspaceId: "ws-attempt-error",
						paneId: "root-attempt-error",
					};
				},
			},
			{
				onFallbackTransition(previous) {
					previousMarkers.push(previous.sessionFile!);
				},
				watch: {
					// Only the second attempt completes a turn. Its settlement and
					// its watcher's exit re-check both fail, so its watcher throws.
					onTurnSettled(turn) {
						if (turn.outcome === "completed")
							throw new Error("injected settlement failure");
					},
					confirmExit() {
						throw new Error("injected exit check failure");
					},
				},
			},
		);
		await start(project, {
			name: "attempt-error",
			task: "Task",
			agent: "native-claude",
			model: "bad, good",
			worktree: { branch: "native/attempt-error" },
		});
		const result = await resultFor("attempt-error");
		assert.match(result.content, /injected exit check failure/);
		assert.equal(previousMarkers.length, 1);
		assert.notEqual(
			result.details.sessionFile,
			previousMarkers[0],
			"the failure is reported for the attempt that failed",
		);
		assert.equal(result.details.native.markerFile, result.details.sessionFile);
		assert.equal(result.details.native.processExit, "confirmed");
		assert.equal(
			existsSync(nativeWorktreeLeaseFile(result.details.worktree.manifestFile)),
			false,
			"the failing attempt's parent-reserved lease is released after its confirmed exit",
		);
		assert.equal(
			running("attempt-error"),
			undefined,
			"no attempt stays listed",
		);
	});

	it("never launches another attempt once the parent aborts between attempts", async (t) => {
		if (!linux) return t.skip("parent reservation identity uses /proc");
		const project = scratch("reg-abort-transition");
		initRepo(project);
		const tree = join(project, "..", "abort-transition-tree");
		let leasePath = "";
		const herdr = useHerdr(
			{
				log: join(project, "..", "abort-transition.json"),
				env: { FAKE_FAIL_MODEL: "bad" },
				createWorktree(_name, cwd, branch, base) {
					execFileSync(
						"git",
						["worktree", "add", "-q", "-b", branch, tree, base],
						{ cwd },
					);
					return {
						path: tree,
						branch,
						workspaceId: "ws-abort-transition",
						paneId: "root-abort-transition",
					};
				},
			},
			{
				onFallbackTransition(previous) {
					leasePath = previous.native!.worktreeLease!;
					previous.abortController?.abort();
				},
			},
		);
		await start(project, {
			name: "abort-transition",
			task: "Task",
			agent: "native-claude",
			model: "bad, good",
			worktree: { branch: "native/abort-transition" },
		});
		const result = await resultFor("abort-transition");
		assert.match(
			result.details.errorMessage,
			/Native fallback launch failed: Subagent cancelled/,
		);
		assert.equal(
			herdr.events.filter((event) => event === "run").length,
			1,
			"only the first attempt was launched",
		);
		assert.equal(
			existsSync(leasePath),
			false,
			"the reservation is released at final settlement",
		);
	});

	it("settles a resumed run whose watcher throws, releasing only after a fresh exit check", async (t) => {
		if (!linux) return t.skip("exit confirmation uses /proc");
		const project = scratch("reg-resume-error");
		useHerdr({ log: join(project, "..", "resume-error-1.json") });
		await start(project, {
			name: "resume-error",
			task: "Task",
			agent: "native-claude",
		});
		const first = await resultFor("resume-error");
		assert.equal(first.details.exitCode, 0, first.content);
		const markerFile = first.details.sessionFile;
		useHerdr(
			{
				log: join(project, "..", "resume-error-2.json"),
				env: { FAKE_EXIT_AFTER_STOP: "1" },
				waitForExit: true,
			},
			{
				watch: {
					onTurnSettled(turn) {
						if (turn.outcome === "completed")
							throw new Error("injected settlement failure");
					},
					confirmExit() {
						throw new Error("injected exit check failure");
					},
				},
			},
		);
		const accepted = await resume(project, {
			sessionPath: markerFile,
			name: "resume-error-2",
			message: "Continue",
		});
		assert.doesNotMatch(accepted.content[0].text, /^Error/);
		const result = await resultFor("resume-error-2");
		assert.match(
			result.content,
			/Native resume error[\s\S]*injected exit check failure[\s\S]*Native marker/,
		);
		assert.equal(result.details.native.processExit, "confirmed");
		assert.equal(
			existsSync(nativeLeaseFile(markerFile)),
			false,
			"the session lease is released after the confirmed exit",
		);
		assert.equal(running("resume-error-2"), undefined);
		assert.equal(
			testApi
				.reconcileUnresolvedNativeRuns()
				.some((entry) => entry.run.markerFile === markerFile),
			false,
		);
	});
});

describe("re-review 3: exit confirmation without /proc fails safe", () => {
	const inspector = (listing: any) => ({
		procRoot: null,
		uid: null,
		isAlive: () => false,
		kill: () => assert.fail("an unverified process is never signalled"),
		listEnvironments: () => listing,
	});
	const exitedRun = () => {
		const dir = scratch("reg-macos");
		const run = createProcessRun("mac-run", join(dir, "process.json"));
		writeFileSync(
			run.receiptFile,
			JSON.stringify({
				version: 1,
				runId: run.id,
				owner: run.ownerToken,
				pid: 777,
				exitCode: 0,
			}),
		);
		return run;
	};

	it("keeps a run unresolved while the listing shows an owned descendant", () => {
		const run = exitedRun();
		const exit = confirmProcessExit(
			run,
			inspector({
				kind: "complete",
				entries: [
					{
						pid: 901,
						ppid: 1,
						pgid: 777,
						text: `sleep 60 PATH=/bin ${OWNER_ENV}=${run.ownerToken}`,
						readable: true,
					},
				],
			}),
		);
		assert.equal(exit.kind, "unconfirmed");
		assert.deepEqual(exit.kind === "unconfirmed" ? exit.lingering : [], [901]);
		const termination = terminateProcessRun(
			{ ...run, receiptFile: `${run.receiptFile}.none` },
			"SIGTERM",
			{
				...inspector({
					kind: "complete",
					entries: [
						{
							pid: 901,
							ppid: 1,
							pgid: 777,
							text: `x ${OWNER_ENV}=${run.ownerToken}`,
							readable: true,
						},
					],
				}),
				// The listed descendant is alive, yet only listed, never proven.
				isAlive: (pid: number) => pid === 901,
			},
		);
		assert.equal(
			termination.kind,
			"unverifiable",
			"listing-only matches are never signalled",
		);
	});

	it("confirms only when a trusted listing proves no owned process remains", () => {
		const run = exitedRun();
		const absent = confirmProcessExit(
			run,
			inspector({
				kind: "complete",
				entries: [
					{
						pid: 902,
						ppid: 1,
						pgid: 902,
						text: "zsh PATH=/bin HOME=/Users/x",
						readable: true,
					},
				],
			}),
		);
		assert.equal(absent.kind, "confirmed");
		const unavailable = confirmProcessExit(
			run,
			inspector({ kind: "unavailable", reason: "ps failed" }),
		);
		assert.equal(unavailable.kind, "unconfirmed");
		assert.match(
			unavailable.kind === "unconfirmed" ? unavailable.reason : "",
			/could not be checked \(ps failed\)/,
		);
	});

	it("trusts a ps listing only when it shows this process's own environment", () => {
		const token = "11111111-1111-4111-8111-111111111111";
		const good = parsePsEnvironments(
			`  10 1 10 node /x PATH=/usr/bin HOME=/h\n  11 10 10 sleep 60 ${OWNER_ENV}=${token} PATH=/bin\n  12 1 12 launchd\n`,
			10,
		);
		assert.equal(good.kind, "complete");
		assert.deepEqual(
			good.kind === "complete"
				? good.entries.map((entry) => entry.readable)
				: [],
			[true, true, false],
		);
		assert.equal(
			parsePsEnvironments("  10 1 10 node /x\n  11 10 10 sleep 60\n", 10).kind,
			"unavailable",
			"a listing without environments cannot prove absence",
		);
		assert.equal(parsePsEnvironments("  11 sleep\n", 10).kind, "unavailable");
	});
});

// ── Final review findings ──────────────────────────────────────────────────

describe("final review 1: unproven potential descendants keep exit unconfirmed", () => {
	const listed = (
		entries: ProcessEnvironmentEntry[],
		isAlive: (pid: number) => boolean = () => false,
	): ProcessInspector => ({
		procRoot: null,
		uid: null,
		isAlive,
		kill: () => assert.fail("an unverified process is never signalled"),
		listEnvironments: () => ({ kind: "complete", entries }),
	});
	const exitedRun = (pid = 777) => {
		const dir = scratch("final-descendant");
		const run = createProcessRun("final-run", join(dir, "process.json"));
		writeFileSync(
			run.receiptFile,
			JSON.stringify({
				version: 1,
				runId: run.id,
				owner: run.ownerToken,
				pid,
				exitCode: 0,
			}),
		);
		return run;
	};
	const hidden = (pid: number, ppid: number | null, pgid: number | null) => ({
		pid,
		ppid,
		pgid,
		text: "",
		readable: false,
	});
	const reasonOf = (exit: ReturnType<typeof confirmProcessExit>) =>
		exit.kind === "unconfirmed" ? exit.reason : "";

	it("discloses an unreadable unrelated process but blocks an unreadable group member", () => {
		const run = exitedRun();
		const unrelated = hidden(950, 1, 950);
		const clean = confirmProcessExit(run, listed([unrelated]));
		assert.equal(clean.kind, "confirmed", "a provable-clean exit confirms");
		assert.equal(clean.kind === "confirmed" && clean.unreadableCount, 1);
		// Orphaned to launchd, but still in the wrapper's process group.
		const orphan = confirmProcessExit(
			run,
			listed([unrelated, hidden(951, 1, 777)]),
		);
		assert.equal(orphan.kind, "unconfirmed");
		assert.match(
			reasonOf(orphan),
			/process\(es\) 951 in the run's process tree or group are still running/,
		);
		// A group member whose environment was scrubbed of the token.
		const scrubbed = confirmProcessExit(
			run,
			listed([
				{
					pid: 952,
					ppid: 1,
					pgid: 777,
					text: "sleep 9 HOME=/x",
					readable: true,
				},
			]),
		);
		assert.equal(scrubbed.kind, "unconfirmed");
	});

	it("follows parent links from owned processes into new groups", () => {
		const run = exitedRun();
		const scan = scanOwnedProcesses(
			run,
			listed([
				{
					pid: 960,
					ppid: 1,
					pgid: 960,
					text: `node PATH=/bin ${OWNER_ENV}=${run.ownerToken}`,
					readable: true,
				},
				hidden(961, 960, 961),
				hidden(962, 961, 962),
				hidden(963, 1, 963),
			]),
		);
		assert.equal(scan.kind, "complete");
		if (scan.kind !== "complete") return;
		assert.deepEqual(scan.pids, [960]);
		assert.deepEqual(scan.related, [961, 962], "child and grandchild");
		assert.deepEqual(scan.unreadable, [963]);
		assert.deepEqual(
			[...relatedProcessIds([hidden(2, 1, 2), hidden(3, 2, 3)], [], [2])],
			[2, 3],
			"a seeded group member and its descendant",
		);
	});

	it("fails closed on incomplete listings and unparseable output", () => {
		const run = exitedRun();
		assert.equal(
			confirmProcessExit(run, listed([hidden(970, null, 970)])).kind,
			"unconfirmed",
			"an unreadable process with an unknown parent may be a descendant",
		);
		assert.equal(
			confirmProcessExit(run, listed([hidden(971, 1, null)])).kind,
			"unconfirmed",
			"an unreadable process with an unknown group may be a descendant",
		);
		assert.equal(
			confirmProcessExit(
				run,
				listed([
					{
						pid: 972,
						ppid: null,
						pgid: null,
						text: "vim HOME=/x",
						readable: true,
					},
				]),
			).kind,
			"confirmed",
			"a readable process without the token and no known relation is not owned",
		);
		assert.equal(
			parsePsEnvironments("garbage first line\n  10 1 10 node PATH=/b\n", 10)
				.kind,
			"unavailable",
		);
		const continued = parsePsEnvironments(
			`  10 1 10 node PATH=/b\n  11 1 11 sh A=1\n${OWNER_ENV}=${run.ownerToken} B=2\n`,
			10,
		);
		assert.equal(continued.kind, "complete");
		if (continued.kind !== "complete") return;
		assert.deepEqual(
			continued.entries.map(({ pid, ppid, pgid }) => [pid, ppid, pgid]),
			[
				[10, 1, 10],
				[11, 1, 11],
			],
		);
		const continuedScan = scanOwnedProcesses(run, listed(continued.entries));
		assert.deepEqual(
			continuedScan.kind === "complete" ? continuedScan.pids : [],
			[11],
			"a token on a continuation line still marks its process",
		);
	});

	it("never treats a provably reused wrapper PID's group as the run's", () => {
		const run = exitedRun();
		const member = hidden(981, 1, 777);
		// The wrapper PID now names a different, readable same-user process.
		const reused = confirmProcessExit(
			run,
			listed([
				{ pid: 777, ppid: 1, pgid: 777, text: "vim HOME=/x", readable: true },
				member,
			]),
		);
		assert.equal(reused.kind, "confirmed");
		// Another user's live process holds the PID (absent from the listing).
		assert.equal(
			confirmProcessExit(
				run,
				listed([member], (pid) => pid === 777),
			).kind,
			"confirmed",
		);
		// Nothing holds the PID: the group can only be the wrapper's.
		assert.equal(confirmProcessExit(run, listed([member])).kind, "unconfirmed");
	});

	it("applies the same rule to /proc, including a zombie wrapper", (t) => {
		if (process.getuid?.() === 0)
			return t.skip("root can read a mode-000 environment");
		const dir = scratch("final-fake-proc");
		const run = createProcessRun("proc-run", join(dir, "process.json"));
		writeFileSync(
			run.receiptFile,
			JSON.stringify({
				version: 1,
				runId: run.id,
				owner: run.ownerToken,
				pid: 600,
				exitCode: 0,
			}),
		);
		const proc = join(dir, "proc");
		const entry = (
			pid: number,
			environ: string | null,
			stat: string | null,
		) => {
			mkdirSync(join(proc, String(pid)), { recursive: true });
			writeFileSync(join(proc, String(pid), "environ"), environ ?? "");
			if (environ === null) chmodSync(join(proc, String(pid), "environ"), 0);
			if (stat) writeFileSync(join(proc, String(pid), "stat"), stat);
		};
		const inspector: ProcessInspector = {
			procRoot: proc,
			uid: process.getuid?.() ?? null,
			isAlive: () => true,
			kill: () => assert.fail("never signals"),
		};
		entry(600, "", "600 (bash) Z 1 600 600");
		entry(601, null, "601 (agent) S 1 600 600");
		const zombie = confirmProcessExit(run, inspector);
		assert.equal(
			zombie.kind,
			"unconfirmed",
			"a zombie wrapper keeps its group",
		);
		assert.match(reasonOf(zombie), /601 in the run's process tree or group/);
		// Reused by a different live process: its group is not the run's.
		writeFileSync(join(proc, "600", "environ"), "HOME=/x\0");
		writeFileSync(join(proc, "600", "stat"), "600 (vim) S 1 600 600");
		const reused = confirmProcessExit(run, inspector);
		assert.equal(reused.kind, "confirmed");
		assert.equal(reused.kind === "confirmed" && reused.unreadableCount, 1);
		// An unreadable process whose stat is unreadable too fails closed.
		entry(602, null, null);
		assert.equal(confirmProcessExit(run, inspector).kind, "unconfirmed");
	});

	it("keeps a real descendant with a scrubbed environment unresolved", async (t) => {
		if (!linux) return t.skip("real descendant scans use /proc");
		const dir = scratch("final-scrubbed");
		const run = createProcessRun("scrub-run", join(dir, "process.json"));
		const script = stageScript(
			supervisedCommand(
				`env -i /bin/sleep 30 >/dev/null 2>&1 & echo $! > ${join(dir, "child.pid")}`,
				run,
			),
			{ scriptPath: join(dir, "scrub.sh") },
		);
		// Detached like a job-control shell's job: the wrapper leads its group.
		const wrapper = spawn("bash", [script], {
			detached: true,
			stdio: "ignore",
		});
		await waitFor(() => readProcessReceipt(run)?.exitCode !== undefined);
		const pid = Number(readFileSync(join(dir, "child.pid"), "utf8"));
		try {
			const exit = confirmProcessExit(run);
			assert.equal(exit.kind, "unconfirmed");
			assert.match(
				reasonOf(exit),
				new RegExp(`${pid} in the run's process tree or group`),
			);
		} finally {
			process.kill(pid, "SIGKILL");
			wrapper.unref();
		}
		await waitFor(() => confirmProcessExit(run).kind === "confirmed");
	});
});

describe("final review 2: unreadable delivery state never ends final delivery", () => {
	const taskResults = (name: string) =>
		sent.filter((message) =>
			new RegExp(`"${name}" completed task`).test(message.content ?? ""),
		);
	const exitNotices = (sessionFile: string) =>
		sent.filter(
			(message) =>
				message.details?.error === "persistent-crash" &&
				message.details?.facts?.sessionFile === sessionFile,
		);
	/** Replace the delivery ledger with a directory: every read and append fails. */
	const breakLedger = (sessionFile: string) => {
		rmSync(`${sessionFile}.ledger`, { force: true });
		mkdirSync(`${sessionFile}.ledger`);
	};
	const repairLedger = (sessionFile: string) =>
		rmSync(`${sessionFile}.ledger`, { recursive: true, force: true });

	it("keeps an owed result through a failing ledger read, then delivers it once", async () => {
		const project = scratch("final-ledger-recover");
		useHerdr({
			log: join(project, "..", "ledger-recover.json"),
			env: { FAKE_EXIT_AFTER_STOP: "1" },
			waitForExit: true,
		});
		sendFailures.match = (message) =>
			/"ledger-spec" completed task/.test(message.content ?? "");
		sendFailures.remaining = 3;
		try {
			await start(project, {
				name: "ledger-spec",
				task: "Only",
				agent: "native-persistent",
			});
			const sessionFile = running("ledger-spec")?.sessionFile ?? "";
			breakLedger(sessionFile);
			await waitFor(() => sendFailures.remaining === 0);
			await new Promise((resolve) => setTimeout(resolve, 120));
			repairLedger(sessionFile);
			await waitFor(() => exitNotices(sessionFile).length === 1);
			assert.equal(taskResults("ledger-spec").length, 1, "delivered once");
			assert.ok(
				sent.indexOf(taskResults("ledger-spec")[0]) <
					sent.indexOf(exitNotices(sessionFile)[0]),
			);
			assert.match(
				exitNotices(sessionFile)[0].content,
				/\(1 settled task result\(s\) delivered before this notice\)/,
			);
			assert.doesNotMatch(
				exitNotices(sessionFile)[0].content,
				/could not be delivered/,
			);
			await new Promise((resolve) => setTimeout(resolve, 200));
			assert.equal(taskResults("ledger-spec").length, 1, "never duplicated");
			assert.equal(exitNotices(sessionFile).length, 1);
		} finally {
			sendFailures.remaining = 0;
		}
	});

	it("carries owed results in the notice when delivery fails through the deadline", async () => {
		const project = scratch("final-ledger-deadline");
		useHerdr(
			{
				log: join(project, "..", "ledger-deadline.json"),
				env: { FAKE_EXIT_AFTER_STOP: "1" },
				waitForExit: true,
			},
			{ deliveryAttempts: 4 },
		);
		sendFailures.match = (message) =>
			/"deadline-spec" completed task/.test(message.content ?? "");
		sendFailures.remaining = 1_000;
		try {
			await start(project, {
				name: "deadline-spec",
				task: "Only",
				agent: "native-persistent",
			});
			const sessionFile = running("deadline-spec")?.sessionFile ?? "";
			breakLedger(sessionFile);
			await waitFor(() => exitNotices(sessionFile).length === 1);
			const notice = exitNotices(sessionFile)[0].content;
			assert.equal(taskResults("deadline-spec").length, 0);
			assert.match(
				notice,
				/\(0 settled task result\(s\) delivered before this notice\)[\s\S]*Task results that could not be delivered separately:\n- [0-9a-f-]{36} \(completed\): Claude fixture result/,
			);
			assert.match(
				notice,
				/Task outcomes: unknown \(the delivery ledger could not be read: EISDIR/,
			);
			await new Promise((resolve) => setTimeout(resolve, 200));
			assert.equal(exitNotices(sessionFile).length, 1, "one notice only");
		} finally {
			sendFailures.remaining = 0;
			repairLedger(running("deadline-spec")?.sessionFile ?? project);
		}
	});

	it("retries a failed exit notice without duplicating it", async () => {
		const project = scratch("final-notice-retry");
		useHerdr({
			log: join(project, "..", "notice-retry.json"),
			env: { FAKE_EXIT_AFTER_STOP: "1" },
			waitForExit: true,
		});
		sendFailures.match = (message) =>
			message.details?.error === "persistent-crash";
		sendFailures.remaining = 2;
		try {
			await start(project, {
				name: "notice-spec",
				task: "Only",
				agent: "native-persistent",
			});
			const sessionFile = running("notice-spec")?.sessionFile ?? "";
			await waitFor(() => exitNotices(sessionFile).length === 1);
			assert.equal(sendFailures.remaining, 0, "two sends failed first");
			await new Promise((resolve) => setTimeout(resolve, 200));
			assert.equal(exitNotices(sessionFile).length, 1);
			assert.equal(taskResults("notice-spec").length, 1);
		} finally {
			sendFailures.remaining = 0;
		}
	});

	it("never types a task whose dispatch cannot be recorded", async () => {
		const project = scratch("final-dispatch-ledger");
		const log = join(project, "..", "dispatch-ledger.json");
		useHerdr({ log });
		await start(project, {
			name: "dispatch-ledger",
			task: "First",
			agent: "native-persistent",
		});
		await waitForMessage((message) =>
			/"dispatch-ledger" completed task/.test(message.content ?? ""),
		);
		const child = running("dispatch-ledger")!;
		await waitFor(() => testApi.persistentSpecialistState(child) === "idle");
		const turnsBefore = child.native!.driver.turns.length;
		breakLedger(child.sessionFile);
		let refused: ReturnType<typeof testApi.handleSubagentSend>;
		try {
			refused = testApi.handleSubagentSend({
				name: "dispatch-ledger",
				message: "Unrecorded",
			});
			await new Promise((resolve) => setTimeout(resolve, 200));
		} finally {
			repairLedger(child.sessionFile);
		}
		assert.match(
			refused.details.error ?? "",
			/did not receive task [0-9a-f-]{36}: its dispatch could not be recorded[\s\S]*Nothing was typed/,
		);
		assert.equal(child.native!.driver.queue.length, 0, "withdrawn");
		assert.equal(child.native!.driver.turns.length, turnsBefore);
		assert.equal(
			fixtureEvents(log).some((event) =>
				(event.input ?? "").includes("Unrecorded"),
			),
			false,
			"never typed into the specialist",
		);
		assert.equal(testApi.persistentSpecialistState(child), "idle");
		assert.equal(
			testApi.handleSubagentSend({ name: "dispatch-ledger", message: "Next" })
				.details.outcome,
			"dispatched",
		);
		await waitForMessage((message) =>
			/"dispatch-ledger" completed task[\s\S]*2 tasks settled/.test(
				message.content ?? "",
			),
		);
		testApi.handleSubagentStop({ name: "dispatch-ledger" }, api);
		await waitForMessage(
			(message) =>
				message.customType === "subagent_stop" &&
				message.details?.facts?.sessionFile === child.sessionFile,
		);
	});

	it("sends a stop notice even when the stop cannot be recorded in the ledger", async () => {
		const project = scratch("final-stop-ledger");
		useHerdr({ log: join(project, "..", "stop-ledger.json") });
		await start(project, {
			name: "stop-ledger",
			task: "First",
			agent: "native-persistent",
		});
		await waitForMessage((message) =>
			/"stop-ledger" completed task/.test(message.content ?? ""),
		);
		const child = running("stop-ledger")!;
		await waitFor(() => testApi.persistentSpecialistState(child) === "idle");
		testApi.handleSubagentStop({ name: "stop-ledger" }, api);
		breakLedger(child.sessionFile);
		try {
			const stopped = await waitForMessage(
				(message) =>
					message.customType === "subagent_stop" &&
					message.details?.facts?.sessionFile === child.sessionFile,
			);
			assert.match(stopped.content, /Persistent specialist stopped\./);
		} finally {
			repairLedger(child.sessionFile);
		}
	});
});

describe("re-review 4: skill snapshot roots cannot be swapped or linked", () => {
	const makeSnapshot = () => {
		const source = join(scratch("reg-snap-src"), "linked-skill");
		mkdirSync(source, { recursive: true });
		writeFileSync(join(source, "SKILL.md"), "Use ref.md\n");
		writeFileSync(join(source, "ref.md"), "reference");
		const root = join(scratch("reg-snap-root"), "native-skills");
		const [skill] = materializeSkills(
			["linked-skill"],
			[
				{
					name: "linked-skill",
					filePath: join(source, "SKILL.md"),
					baseDir: source,
				},
			],
			new Set(["read"]),
			root,
		);
		writeSkillSnapshots([skill]);
		return { root, snapshot: skill.snapshot!, skill };
	};
	const copyDir = (from: string, to: string) =>
		execFileSync("cp", ["-a", from, to]);

	it("rejects a symlinked snapshot root or snapshot directory", () => {
		const { root, snapshot } = makeSnapshot();
		assert.equal(verifySkillSnapshot(snapshot.dir, snapshot.sha256), null);
		// The snapshot directory replaced by a link to an identical copy.
		const copy = join(scratch("reg-snap-copy"), snapshot.sha256);
		copyDir(snapshot.dir, copy);
		execFileSync("rm", ["-rf", snapshot.dir]);
		symlinkSync(copy, snapshot.dir);
		assert.match(
			verifySkillSnapshot(snapshot.dir, snapshot.sha256) ?? "",
			/snapshot .* is not a real directory/,
		);
		// The root replaced by a link to a directory holding a matching copy.
		const altRoot = join(scratch("reg-snap-alt"), "native-skills");
		mkdirSync(altRoot, { recursive: true });
		copyDir(copy, join(altRoot, snapshot.sha256));
		execFileSync("rm", ["-rf", root]);
		symlinkSync(altRoot, root);
		assert.match(
			verifySkillSnapshot(snapshot.dir, snapshot.sha256) ?? "",
			/snapshot root .* is not a real directory/,
		);
		assert.throws(
			() =>
				writeSkillSnapshots([
					{
						...makeSnapshot().skill,
						snapshot: {
							...snapshot,
							dir: join(root, "0".repeat(64)),
							sha256: "0".repeat(64),
						},
					},
				]),
			/snapshot root .* is not a real directory/,
		);
	});

	it("fails closed when the snapshot is swapped during verification", () => {
		const { snapshot } = makeSnapshot();
		const holding = join(scratch("reg-snap-swap"), "held");
		const reason = verifySkillSnapshot(snapshot.dir, snapshot.sha256, {
			afterWalk() {
				// Replace the verified directory with an identical-looking copy.
				renameSync(snapshot.dir, holding);
				copyDir(holding, snapshot.dir);
			},
		});
		assert.match(reason ?? "", /changed during verification/);
		// A file swapped for a link to identical content is rejected too.
		const { snapshot: other } = makeSnapshot();
		const target = join(scratch("reg-snap-target"), "ref.md");
		writeFileSync(target, "reference");
		chmodSync(join(other.dir, "ref.md"), 0o600);
		execFileSync("rm", ["-f", join(other.dir, "ref.md")]);
		symlinkSync(target, join(other.dir, "ref.md"));
		assert.match(
			verifySkillSnapshot(other.dir, other.sha256) ?? "",
			/unexpected entry ref\.md/,
		);
	});

	it("binds snapshots to the session's artifact directory and rechecks before launch", () => {
		const { snapshot } = makeSnapshot();
		const artifacts = scratch("reg-snap-artifacts");
		const markerFile = join(artifacts, "native-sessions", "m.json");
		const loadout = {
			tools: "read",
			nativeTools: ["Read"],
			model: null,
			thinking: null,
			promptMode: null,
			identitySha256: null,
			mode: "autonomous" as const,
			sessionMode: "standalone" as const,
			skills: [
				{
					name: "linked-skill",
					filePath: "/x/SKILL.md",
					sha256: "a".repeat(64),
					bytes: 1,
					snapshot: { dir: snapshot.dir, sha256: snapshot.sha256 },
				},
			],
			spawnAgents: null,
		};
		const marker = {
			version: 2 as const,
			type: "native_session" as const,
			harness: "claude" as const,
			nativeSessionId: "44444444-4444-4444-8444-444444444444",
			sessionKey: "k",
			runId: "k",
			name: "n",
			cwd: artifacts,
			createdAt: 0,
			loadout,
			loadoutSha256: loadoutSha256(loadout),
		};
		assert.match(
			verifyNativeSessionMarker(marker, markerFile) ?? "",
			/snapshot is outside the session's artifact directory/,
		);
		// Inside its own artifact directory it verifies, until tampered with
		// between the resume check and the launch.
		const bound = join(artifacts, "native-skills", snapshot.sha256);
		mkdirSync(join(artifacts, "native-skills"), { recursive: true });
		copyDir(snapshot.dir, bound);
		const boundLoadout = {
			...loadout,
			skills: [
				{
					...loadout.skills[0],
					snapshot: { dir: bound, sha256: snapshot.sha256 },
				},
			],
		};
		const boundMarker = {
			...marker,
			loadout: boundLoadout,
			loadoutSha256: loadoutSha256(boundLoadout),
		};
		assert.equal(verifyNativeSessionMarker(boundMarker, markerFile), null);
		chmodSync(join(bound, "ref.md"), 0o600);
		writeFileSync(join(bound, "ref.md"), "tampered after the check");
		assert.throws(
			() =>
				prepareNativeRun({
					id: "recheck",
					artifactDir: artifacts,
					cwd: artifacts,
					name: "n",
					resume: {
						marker: boundMarker,
						markerFile,
						message: "m",
						mode: "autonomous",
					},
				}),
			/Native resume refused: the session its skill "linked-skill" snapshot/,
		);
	});

	it("launches a resume only with the identity text it verified", () => {
		const dir = scratch("reg-identity");
		const identityFile = join(dir, "run.identity.md");
		writeFileSync(identityFile, "Recorded identity");
		const loadout = {
			tools: "read",
			nativeTools: ["Read"],
			model: null,
			thinking: null,
			promptMode: null,
			identitySha256: createHash("sha256")
				.update("Recorded identity")
				.digest("hex"),
			mode: "autonomous" as const,
			sessionMode: "standalone" as const,
			skills: [],
			spawnAgents: null,
		};
		const marker = {
			version: 2 as const,
			type: "native_session" as const,
			harness: "claude" as const,
			nativeSessionId: "55555555-5555-4555-8555-555555555555",
			sessionKey: "k",
			runId: "k",
			name: "n",
			cwd: dir,
			createdAt: 0,
			identityFile,
			loadout,
			loadoutSha256: loadoutSha256(loadout),
		};
		assert.equal(readIdentityText(marker), "Recorded identity");
		// Replaced after the marker check: the text that would launch is
		// refused rather than trusted from a second, unverified read.
		writeFileSync(identityFile, "Replaced identity");
		assert.throws(
			() => readIdentityText(marker),
			/role identity file changed after verification/,
		);
		assert.equal(
			readIdentityText({
				...marker,
				loadout: { ...loadout, identitySha256: null },
			}),
			null,
		);
	});
});

describe("final review 3: every nested snapshot entry is pinned until verified", () => {
	const makeNested = () => {
		const source = join(scratch("final-snap-src"), "nested-skill");
		mkdirSync(join(source, "lib", "deep"), { recursive: true });
		writeFileSync(join(source, "SKILL.md"), "Use lib/helper.md\n");
		writeFileSync(join(source, "lib", "helper.md"), "helper v1");
		writeFileSync(join(source, "lib", "deep", "data.md"), "data v1");
		const root = join(scratch("final-snap-root"), "native-skills");
		const [skill] = materializeSkills(
			["nested-skill"],
			[
				{
					name: "nested-skill",
					filePath: join(source, "SKILL.md"),
					baseDir: source,
				},
			],
			new Set(["read"]),
			root,
		);
		writeSkillSnapshots([skill]);
		const snapshot = skill.snapshot!;
		assert.equal(verifySkillSnapshot(snapshot.dir, snapshot.sha256), null);
		return snapshot;
	};
	const changed = /snapshot .* changed during verification/;

	it("fails closed when a nested directory is replaced after it was read", () => {
		const snapshot = makeNested();
		const lib = join(snapshot.dir, "lib");
		const reason = verifySkillSnapshot(snapshot.dir, snapshot.sha256, {
			afterWalk() {
				renameSync(lib, join(scratch("final-snap-held"), "lib"));
				mkdirSync(join(lib, "deep"), { recursive: true });
				writeFileSync(join(lib, "helper.md"), "helper EVIL");
				writeFileSync(join(lib, "deep", "data.md"), "data EVIL");
			},
		});
		assert.match(reason ?? "", changed);
	});

	it("fails closed when a nested file is edited or replaced after it was read", () => {
		const snapshot = makeNested();
		const data = join(snapshot.dir, "lib", "deep", "data.md");
		const edited = verifySkillSnapshot(snapshot.dir, snapshot.sha256, {
			afterWalk() {
				chmodSync(data, 0o600);
				writeFileSync(data, "data v2"); // same length, new content
			},
		});
		assert.match(edited ?? "", changed);

		// Identical bytes under a new inode are still a replacement.
		const other = makeNested();
		const helper = join(other.dir, "lib", "helper.md");
		const replaced = verifySkillSnapshot(other.dir, other.sha256, {
			afterWalk() {
				const copy = `${helper}.copy`;
				writeFileSync(copy, readFileSync(helper));
				renameSync(copy, helper);
			},
		});
		assert.match(replaced ?? "", changed);
	});

	it("rejects hard links, nested symbolic links, and special files", () => {
		const linked = makeNested();
		linkSync(
			join(linked.dir, "lib", "helper.md"),
			join(scratch("final-snap-alias"), "alias.md"),
		);
		assert.match(
			verifySkillSnapshot(linked.dir, linked.sha256) ?? "",
			/entry lib\/helper\.md is a hard link/,
		);
		const symlinked = makeNested();
		const deep = join(symlinked.dir, "lib", "deep");
		const held = join(scratch("final-snap-deep"), "deep");
		renameSync(deep, held);
		symlinkSync(held, deep);
		assert.match(
			verifySkillSnapshot(symlinked.dir, symlinked.sha256) ?? "",
			/unexpected entry lib\/deep/,
		);
		const special = makeNested();
		execFileSync("mkfifo", [join(special.dir, "lib", "pipe")]);
		assert.match(
			verifySkillSnapshot(special.dir, special.sha256) ?? "",
			/unexpected entry lib\/pipe/,
		);
	});
});

describe("final review 4: an abort during launch never dispatches a process", () => {
	const worktreeHerdr = (
		project: string,
		label: string,
		waitForShellReady: (surface: string, call: number) => Promise<void>,
		seam: Parameters<typeof useHerdr>[1] = {},
	) => {
		const tree = join(project, "..", `${label}-tree`);
		return useHerdr(
			{
				log: join(project, "..", `${label}.json`),
				env: { FAKE_FAIL_MODEL: "bad" },
				waitForShellReady,
				createWorktree(_name, cwd, branch, base) {
					execFileSync(
						"git",
						["worktree", "add", "-q", "-b", branch, tree, base],
						{ cwd },
					);
					return {
						path: tree,
						branch,
						workspaceId: `ws-${label}`,
						paneId: `root-${label}`,
					};
				},
			},
			seam,
		);
	};
	const pause = (ms: number) =>
		new Promise<void>((resolve) => setTimeout(resolve, ms));

	it("stops a fallback attempt blocked on shell readiness", async (t) => {
		if (!linux) return t.skip("parent reservation identity uses /proc");
		const project = scratch("final-abort-ready");
		initRepo(project);
		let previous: ReturnType<typeof running>;
		const herdr = worktreeHerdr(
			project,
			"abort-ready",
			async (_surface, call) => {
				if (call !== 2) return;
				// The parent shuts down while the retained shell is not ready.
				previous?.abortController?.abort();
				await pause(100);
			},
			{
				onFallbackTransition(attempt) {
					previous = attempt;
				},
			},
		);
		await start(project, {
			name: "abort-ready",
			task: "Task",
			agent: "native-claude",
			model: "bad, good",
			worktree: { branch: "native/abort-ready" },
		});
		const result = await resultFor("abort-ready");
		assert.match(
			result.details.errorMessage,
			/Native launch cancelled before its process was dispatched/,
		);
		await pause(200);
		assert.equal(
			herdr.events.filter((event) => event === "run").length,
			1,
			"no command was dispatched for the aborted attempt",
		);
		assert.equal(herdr.children.length, 1, "no second child process");
		assert.equal(
			existsSync(previous!.native!.worktreeLease!),
			false,
			"a never-started attempt releases the reservation",
		);
	});

	it("stops a fresh launch when its call is cancelled during readiness", async () => {
		const project = scratch("final-abort-fresh");
		const controller = new AbortController();
		const herdr = useHerdr({
			log: join(project, "..", "abort-fresh.json"),
			async waitForShellReady() {
				controller.abort();
				await pause(100);
			},
		});
		await assert.rejects(
			testApi.startSubagentRun(
				api,
				{ name: "abort-fresh", task: "Task", agent: "native-claude" },
				ctxFor(project),
				{ signal: controller.signal },
			),
			/Native launch cancelled before its process was dispatched/,
		);
		await pause(200);
		assert.equal(herdr.events.includes("run"), false);
		assert.equal(herdr.children.length, 0);
		assert.equal(herdr.closed.length, 1, "the launch's own pane is closed");
		assert.equal(running("abort-fresh"), undefined);
	});

	it("stops an initial launch when the parent shuts down during readiness", async () => {
		const project = scratch("final-abort-quit");
		const herdr = useHerdr({
			log: join(project, "..", "abort-quit.json"),
			async waitForShellReady() {
				await shutdownParent("quit");
				await pause(100);
			},
		});
		await assert.rejects(
			testApi.startSubagentRun(
				api,
				{ name: "abort-quit", task: "Task", agent: "native-claude" },
				ctxFor(project),
			),
			/Native launch cancelled before its process was dispatched/,
		);
		await pause(200);
		assert.equal(herdr.events.includes("run"), false);
		assert.equal(herdr.children.length, 0);
		// A later launch in a new session is not affected by the old abort.
		const next = useHerdr({ log: join(project, "..", "after-quit.json") });
		await start(project, {
			name: "after-quit",
			task: "Task",
			agent: "native-claude",
		});
		const result = await resultFor("after-quit");
		assert.equal(result.details.exitCode, 0, result.content);
		assert.equal(next.events.filter((event) => event === "run").length, 1);
	});
});

describe("final review 5: an unresolved fallback attempt is the primary result", () => {
	it("reports the live unresolved attempt's marker, session, model, and pane", async (t) => {
		if (!linux) return t.skip("unresolved exits are proven with /proc");
		const project = scratch("final-unresolved-fallback");
		let previous: ReturnType<typeof running>;
		const herdr = useHerdr(
			{
				log: join(project, "..", "unresolved-fallback.json"),
				mode: "hang",
				env: { FAKE_FAIL_MODEL: "bad" },
				failAfterRun: 2,
			},
			{
				onFallbackTransition(attempt) {
					previous = attempt;
				},
			},
		);
		await start(project, {
			name: "unresolved-fb",
			task: "Task",
			agent: "native-claude",
			model: "bad, good",
		});
		const result = await resultFor("unresolved-fb");
		const details = result.details;
		const first = previous!;
		const unresolved = testApi
			.reconcileUnresolvedNativeRuns()
			.find((entry) => entry.run.model === "good");
		assert.ok(unresolved, "attempt two is tracked as unresolved");
		const marker = unresolved.run.markerFile;
		assert.notEqual(marker, first.sessionFile);
		assert.equal(details.sessionFile, marker, "top-level session");
		assert.equal(details.native.markerFile, marker, "primary marker");
		assert.equal(
			details.native.sessionId,
			markerV2(marker).nativeSessionId,
			"primary native session",
		);
		assert.equal(details.native.model, "good", "primary model");
		assert.equal(details.native.processExit, "unconfirmed");
		assert.notEqual(details.native.surface, first.surface);
		assert.equal(
			details.native.surface,
			`pane-${herdr.events.filter((event) => event.startsWith("create:")).length}`,
		);
		assert.ok(
			details.native.retained.includes(`pane ${details.native.surface}`),
		);
		assert.ok(details.native.retained.includes(unresolved.run.runDir));
		assert.equal(details.native.resume.available, false);
		assert.match(
			details.errorMessage,
			/^Native fallback attempt good failed after dispatch and its process exit is unconfirmed: [\s\S]*Earlier attempt bad failed: /,
		);
		assert.match(result.content, new RegExp(`Native marker: ${marker}`));
		assert.match(
			result.content,
			new RegExp(`Native pane: ${details.native.surface}`),
		);
		assert.doesNotMatch(
			result.content,
			new RegExp(`Native marker: ${first.sessionFile}`),
			"the finished first attempt is history, not the primary reference",
		);
		assert.deepEqual(
			details.fallbackFailures.map((failure: { error: string }) =>
				failure.error.includes(`(marker ${first.sessionFile})`)
					? "first"
					: failure.error.includes(`(marker ${marker})`)
						? "second"
						: "unknown",
			),
			["first", "second"],
		);
		assert.equal(
			herdr.closed.includes(details.native.surface),
			false,
			"the live attempt's pane is retained",
		);
		for (const child of herdr.children) killGroup(child.pid);
		await waitFor(() =>
			testApi
				.reconcileUnresolvedNativeRuns()
				.every((entry) => entry.run.markerFile !== marker),
		);
	});
});

describe("acceptance: a persistent first task is durable before its process", () => {
	const sessionsDir = (project: string) =>
		join(
			parentSession(project).sessionDir,
			"artifacts",
			"parent",
			"native-sessions",
		);
	const artifactDir = (project: string) =>
		join(parentSession(project).sessionDir, "artifacts", "parent");
	const outcomes = (markerFile: string) =>
		readPersistentDeliveryLedger(markerFile).map((entry) => entry.outcome);
	const onlyLedger = (project: string) => {
		const ledgers = readdirSync(sessionsDir(project)).filter((name) =>
			name.endsWith(".json.ledger"),
		);
		assert.equal(ledgers.length, 1);
		return join(sessionsDir(project), ledgers[0]);
	};

	it("does not confirm exit when a late-start marker cannot be written", () => {
		const project = scratch("accept-confirm-cancel-fail");
		const run = createProcessRun(
			"cancel-fail",
			join(project, "missing", "process.json"),
		);
		const result = confirmProcessExit(run, {
			procRoot: null,
			uid: null,
			isAlive: () => false,
			kill: () => assert.fail("nothing is signalled"),
			listEnvironments: () => ({ kind: "complete", entries: [] }),
		});
		assert.equal(result.kind, "unconfirmed");
		assert.match(
			result.kind === "unconfirmed" ? result.reason : "",
			/late-start cancel marker could not be written/,
		);
	});

	it("launches nothing when the ledger cannot be written", async () => {
		const project = scratch("accept-ledger-preflight");
		mkdirSync(join(parentSession(project).sessionDir, "artifacts", "parent"), {
			recursive: true,
		});
		// A file where the sessions directory belongs: no ledger can exist.
		writeFileSync(sessionsDir(project), "not a directory");
		const herdr = useHerdr({ log: join(project, "..", "preflight.json") });
		await assert.rejects(
			testApi.startSubagentRun(
				api,
				{ name: "preflight-spec", task: "Only", agent: "native-persistent" },
				ctxFor(project),
			),
			/ENOTDIR|EEXIST/,
		);
		assert.deepEqual(herdr.events, [], "no pane, readiness wait, or dispatch");
		assert.equal(herdr.children.length, 0);
		assert.equal(running("preflight-spec"), undefined);
		assert.equal(
			existsSync(join(artifactDir(project), "native-runs")),
			false,
			"no run was prepared",
		);
	});

	it("records a planned launch that fails before dispatch as abandoned", async () => {
		const project = scratch("accept-planned-fail");
		const herdr = useHerdr({
			log: join(project, "..", "planned-fail.json"),
			failBeforeRun: true,
		});
		await assert.rejects(
			testApi.startSubagentRun(
				api,
				{ name: "planned-fail", task: "Only", agent: "native-persistent" },
				ctxFor(project),
			),
			/herdr refused to run the script/,
		);
		const ledger = onlyLedger(project);
		const markerFile = ledger.slice(0, -".ledger".length);
		assert.deepEqual(outcomes(markerFile), ["planned", "abandoned"]);
		assert.equal(herdr.children.length, 0, "no process");
		assert.equal(herdr.closed.length, 1, "the launch's pane is closed");
		assert.equal(running("planned-fail"), undefined, "no active task");
		assert.deepEqual(
			testApi.recoverPlannedPersistentDispatches(artifactDir(project)),
			[],
			"nothing left to recover",
		);
	});

	it("keeps an unresolved post-dispatch failure planned until its exit is confirmed", async (t) => {
		if (!linux) return t.skip("unresolved exits are proven with /proc");
		const project = scratch("accept-unresolved");
		const herdr = useHerdr({
			log: join(project, "..", "unresolved.json"),
			mode: "hang",
			failAfterRun: true,
		});
		await assert.rejects(
			testApi.startSubagentRun(
				api,
				{ name: "unresolved-spec", task: "Only", agent: "native-persistent" },
				ctxFor(project),
			),
			(error: Error) => error instanceof NativeLaunchUnresolvedError,
		);
		const markerFile = onlyLedger(project).slice(0, -".ledger".length);
		assert.deepEqual(
			outcomes(markerFile),
			["planned"],
			"undecided, not active",
		);
		assert.ok(
			testApi
				.reconcileUnresolvedNativeRuns()
				.some((entry) => entry.run.markerFile === markerFile),
			"the live process is tracked, never untracked",
		);
		await startParentSession(project);
		assert.deepEqual(
			outcomes(markerFile),
			["planned"],
			"never recovered while tracked",
		);
		for (const child of herdr.children) killGroup(child.pid);
		await waitFor(() =>
			testApi
				.reconcileUnresolvedNativeRuns()
				.every((entry) => entry.run.markerFile !== markerFile),
		);
		await startParentSession(project);
		assert.deepEqual(outcomes(markerFile), ["planned", "dispatched"]);
	});

	it("commits a successful launch and supervises it", async () => {
		const project = scratch("accept-commit");
		useHerdr({ log: join(project, "..", "commit.json") });
		const started = await start(project, {
			name: "commit-spec",
			task: "Only",
			agent: "native-persistent",
		});
		assert.equal(started.details.warning, undefined);
		const child = running("commit-spec")!;
		assert.deepEqual(outcomes(child.sessionFile).slice(0, 2), [
			"planned",
			"dispatched",
		]);
		const [planned, dispatched] = readPersistentDeliveryLedger(
			child.sessionFile,
		);
		assert.equal(planned.task, child.taskId);
		assert.equal(dispatched.task, planned.task);
		assert.equal(planned.policyHash, child.policyHash);
		await waitForMessage((message) =>
			/"commit-spec" completed task/.test(message.content ?? ""),
		);
		testApi.handleSubagentStop({ name: "commit-spec" }, api);
		await waitForMessage(
			(message) =>
				message.customType === "subagent_stop" &&
				message.details?.facts?.sessionFile === child.sessionFile,
		);
	});

	it("keeps a live specialist supervised when its dispatch cannot be committed", async (t) => {
		if (process.getuid?.() === 0)
			return t.skip("root can append to a read-only ledger");
		const project = scratch("accept-commit-fail");
		let ledger = "";
		useHerdr({
			log: join(project, "..", "commit-fail.json"),
			onRun() {
				// `planned` is recorded; the commit after dispatch will fail.
				ledger = onlyLedger(project);
				chmodSync(ledger, 0o400);
			},
		});
		try {
			const started = await start(project, {
				name: "commit-fail",
				task: "Only",
				agent: "native-persistent",
			});
			assert.match(
				started.details.warning ?? "",
				/dispatch could not be committed[\s\S]*supervised/,
			);
			assert.match(
				started.content[0].text,
				/Warning: the first task's dispatch/,
			);
			const child = running("commit-fail");
			assert.ok(child, "registered, never untracked");
			assert.deepEqual(outcomes(child.sessionFile), ["planned"]);
			await waitForMessage((message) =>
				/"commit-fail" completed task/.test(message.content ?? ""),
			);
			assert.deepEqual(
				testApi.recoverPlannedPersistentDispatches(artifactDir(project)),
				[],
				"a supervised specialist's plan is never recovered underneath it",
			);
			chmodSync(ledger, 0o600);
			testApi.handleSubagentStop({ name: "commit-fail" }, api);
			await waitForMessage(
				(message) =>
					message.customType === "subagent_stop" &&
					message.details?.facts?.sessionFile === child.sessionFile,
			);
		} finally {
			if (ledger) chmodSync(ledger, 0o600);
		}
	});

	it("never recovers a plan whose launch is still in flight across /reload", async () => {
		const project = scratch("accept-reload");
		const recovered: unknown[] = [];
		let cancelMarker = "";
		useHerdr({
			log: join(project, "..", "reload.json"),
			onRun() {
				// A /reload while the planned launch is dispatching.
				subagentsModule.default(api);
				recovered.push(
					...testApi.recoverPlannedPersistentDispatches(artifactDir(project)),
				);
				const markerFile = onlyLedger(project).slice(0, -".ledger".length);
				const id = markerFile.split("/").pop()!.slice(0, -".json".length);
				cancelMarker = join(
					artifactDir(project),
					"native-runs",
					id,
					"process.json.cancel",
				);
			},
		});
		await start(project, {
			name: "reload-spec",
			task: "Only",
			agent: "native-persistent",
		});
		assert.deepEqual(recovered, []);
		assert.equal(
			existsSync(cancelMarker),
			false,
			"the launch was never cancelled",
		);
		const child = running("reload-spec")!;
		assert.deepEqual(outcomes(child.sessionFile).slice(0, 2), [
			"planned",
			"dispatched",
		]);
		await waitForMessage((message) =>
			/"reload-spec" completed task/.test(message.content ?? ""),
		);
		testApi.handleSubagentStop({ name: "reload-spec" }, api);
		await waitForMessage(
			(message) =>
				message.customType === "subagent_stop" &&
				message.details?.facts?.sessionFile === child.sessionFile,
		);
	});

	it("leaves a plan unresolved when its late-start marker cannot be written", () => {
		const project = scratch("accept-cancel-fail");
		mkdirSync(sessionsDir(project), { recursive: true });
		const markerFile = join(sessionsDir(project), "cancel-fail.json");
		appendFileSync(
			`${markerFile}.ledger`,
			`${JSON.stringify({
				task: "task-cancel-fail",
				outcome: "planned",
				generation: "cancel-fail",
				logicalId: "cancel-fail",
				policyHash: "a".repeat(64),
				at: "2026-09-29T00:00:00.000Z",
			})}\n`,
		);
		const recovered = testApi.recoverPlannedPersistentDispatches(
			artifactDir(project),
			() => false,
		);
		assert.deepEqual(recovered, []);
		assert.deepEqual(outcomes(markerFile), ["planned"]);
	});

	it("resolves a crashed parent's planned tasks at session start", async (t) => {
		if (!linux) return t.skip("the late-start check runs a real wrapper");
		const project = scratch("accept-crash");
		const sessions = sessionsDir(project);
		mkdirSync(sessions, { recursive: true });
		const plan = (id: string, extra: string[] = []) => {
			const markerFile = join(sessions, `${id}.json`);
			const entry = {
				task: `task-${id}`,
				generation: id,
				logicalId: id,
				policyHash: "a".repeat(64),
				at: "2026-09-29T00:00:00.000Z",
			};
			for (const outcome of ["planned", ...extra])
				appendFileSync(
					`${markerFile}.ledger`,
					`${JSON.stringify({ ...entry, outcome })}\n`,
				);
			const runDir = join(artifactDir(project), "native-runs", id);
			mkdirSync(runDir, { recursive: true });
			return {
				markerFile,
				run: createProcessRun(id, join(runDir, "process.json")),
			};
		};
		// Crashed before dispatch: no start receipt.
		const never = plan("never");
		// Crashed after dispatch, before the commit: the wrapper started.
		const started = plan("started");
		writeFileSync(started.run.receiptFile, JSON.stringify({ pid: 1 }));
		// Already committed before the crash.
		const committed = plan("committed", ["dispatched"]);
		await startParentSession(project);
		assert.deepEqual(outcomes(never.markerFile), ["planned", "abandoned"]);
		assert.deepEqual(outcomes(started.markerFile), ["planned", "dispatched"]);
		assert.deepEqual(outcomes(committed.markerFile), ["planned", "dispatched"]);
		// The abandoned launch can never start late: its wrapper sees the
		// cancel marker after its start receipt and never runs the command.
		const ran = join(project, "..", "late-start-ran");
		const script = stageScript(supervisedCommand(`touch ${ran}`, never.run), {
			scriptPath: join(project, "..", "late.sh"),
		});
		assert.throws(
			() => execFileSync("bash", [script], { stdio: "ignore" }),
			(error: { status?: number }) => error.status === 125,
		);
		assert.equal(existsSync(ran), false);
		// Idempotent: a second session start changes nothing.
		await startParentSession(project);
		assert.deepEqual(outcomes(never.markerFile), ["planned", "abandoned"]);
	});
});

describe("automatic native launch guards and environment", () => {
	/** A package guard recording boundaries and the latch it holds. */
	function recordingGuard(
		events: string[],
		stopAt?: "beforeResources" | "commitDispatch",
	) {
		const guard = {
			state: "uncommitted",
			beforeResources() {
				events.push("guard:resources");
				if (stopAt === "beforeResources")
					throw new Error("stale before resources");
			},
			resourcesCreated() {
				events.push("guard:created");
				guard.state = "resources-created";
			},
			commitDispatch() {
				events.push("guard:dispatch");
				if (stopAt === "commitDispatch")
					throw new Error("stale before dispatch");
				guard.state = "dispatch-attempted";
			},
		};
		return guard;
	}
	const markerFor = (request: ReturnType<typeof nativeRequest>) =>
		nativeSessionMarkerPath(request.parent, request.id!);
	const settleChildren = async (herdr: ReturnType<typeof fakeHerdr>) => {
		for (const child of herdr.children) killGroup(child.pid);
		await new Promise((resolve) => setTimeout(resolve, 50));
	};

	it("creates no pane when the guard is stale before resources", async () => {
		const project = scratch("auto-native-stale");
		const herdr = fakeHerdr({ log: join(project, "..", "stale.json") });
		const guard = recordingGuard(herdr.events, "beforeResources");
		await assert.rejects(
			launchNativeSubagent(
				nativeRequest(project, "claude", { automatic: { guard } }),
				herdr.operations,
				nativeOperations,
			),
			/stale before resources/,
		);
		assert.deepEqual(herdr.events, ["guard:resources"]);
		assert.deepEqual(herdr.closed, []);
		assert.equal(guard.state, "uncommitted");
	});

	it("dispatches no process when aborted during the shell wait", async () => {
		const project = scratch("auto-native-abort");
		const controller = new AbortController();
		let leaseDuringWait = false;
		const herdr = fakeHerdr({
			log: join(project, "..", "abort.json"),
			// The shell never becomes ready on its own.
			waitForShellReady: () => {
				leaseDuringWait = existsSync(nativeLeaseFile(markerFor(request)));
				setTimeout(() => controller.abort(), 20);
				return new Promise<void>(() => {});
			},
		});
		const guard = recordingGuard(herdr.events);
		const request = nativeRequest(project, "claude", {
			automatic: { guard },
			signal: controller.signal,
		});
		await assert.rejects(
			launchNativeSubagent(request, herdr.operations, nativeOperations),
			/Native launch cancelled before its process was dispatched/,
		);
		assert.deepEqual(herdr.events, [
			"guard:resources",
			"create:Native worker",
			"guard:created",
			"ready",
		]);
		assert.equal(guard.state, "resources-created");
		assert.equal(herdr.children.length, 0);
		// Never dispatched: exit is confirmed, so the owned pane and session
		// lease are released through the existing confirmed-exit cleanup.
		assert.deepEqual(herdr.closed, ["pane-1"]);
		assert.equal(leaseDuringWait, true, "the prepared run held its lease");
		assert.equal(existsSync(nativeLeaseFile(markerFor(request))), false);
	});

	it("dispatches no process when the guard fails after readiness", async () => {
		const project = scratch("auto-native-drift");
		const herdr = fakeHerdr({ log: join(project, "..", "drift.json") });
		const guard = recordingGuard(herdr.events, "commitDispatch");
		const request = nativeRequest(project, "kiro", { automatic: { guard } });
		await assert.rejects(
			launchNativeSubagent(request, herdr.operations, nativeOperations),
			/stale before dispatch/,
		);
		assert.deepEqual(herdr.events.slice(-2), ["ready", "guard:dispatch"]);
		assert.equal(herdr.events.includes("run"), false);
		assert.equal(herdr.children.length, 0);
		assert.deepEqual(herdr.closed, ["pane-1"]);
		assert.equal(existsSync(nativeLeaseFile(markerFor(request))), false);
		assert.equal(existsSync(join(project, ".kiro")), false, "profile removed");
	});

	it("keeps the latch when runScript throws after sending", async () => {
		const project = scratch("auto-native-lost");
		const herdr = fakeHerdr({
			log: join(project, "..", "lost.json"),
			failAfterRun: true,
		});
		const guard = recordingGuard(herdr.events);
		await assert.rejects(
			launchNativeSubagent(
				nativeRequest(project, "claude", { automatic: { guard } }),
				herdr.operations,
				nativeOperations,
			),
			/acknowledgement was lost/,
		);
		assert.equal(guard.state, "dispatch-attempted");
		assert.equal(herdr.events.filter((event) => event === "run").length, 1);
		await settleChildren(herdr);
	});

	it("rejects an automatic resume, reuse, or caller surface before resources", async () => {
		const project = scratch("auto-native-shape");
		const herdr = fakeHerdr({ log: join(project, "..", "shape.json") });
		await assert.rejects(
			launchNativeSubagent(
				nativeRequest(project, "claude", {
					automatic: { guard: recordingGuard(herdr.events) },
					surface: "caller-pane",
				}),
				herdr.operations,
				nativeOperations,
			),
			/only a fresh launch in its own ordinary pane/,
		);
		assert.deepEqual(herdr.events, []);
	});

	it("strips the Jev key and marks only automatic native children", async () => {
		const observed = new Map<
			string,
			{ typesafeKey: string | null; autoRoutingDisabled: string | null }
		>();
		for (const kind of ["manual", "automatic"] as const) {
			const project = scratch(`auto-native-env-${kind}`);
			const log = join(project, "..", `env-${kind}.json`);
			const herdr = fakeHerdr({
				log,
				env: { TYPESAFE_API_KEY: "parent-secret" },
			});
			const running = await launchNativeSubagent(
				nativeRequest(
					project,
					"claude",
					kind === "automatic" ? { automatic: {} } : {},
				),
				herdr.operations,
				nativeOperations,
			);
			await waitFor(() => existsSync(log));
			observed.set(kind, JSON.parse(readFileSync(log, "utf8")));
			const script = readFileSync(running.launchScriptFile, "utf8");
			assert.equal(
				script.includes("unset TYPESAFE_API_KEY"),
				kind === "automatic",
			);
			await settleChildren(herdr);
		}
		assert.equal(observed.get("manual")?.typesafeKey, "parent-secret");
		assert.equal(observed.get("manual")?.autoRoutingDisabled, null);
		assert.equal(observed.get("automatic")?.typesafeKey, null);
		assert.equal(observed.get("automatic")?.autoRoutingDisabled, "1");
		assert.equal(process.env.PI_HERDR_AUTO_ROUTING_DISABLED, undefined);
	});
});
